package org.sleepwell.app;
import android.content.*;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import java.nio.file.Files;import java.util.*;import static org.junit.Assert.*;
/** Effective-category/date/count/paging checks on real isolated SQLite and real synthetic WAV bytes. No hardware. */
public final class SoundCategoryStorageTest {
 @org.junit.Before public void privateCiOnly(){assertEquals("true",InstrumentationRegistry.getArguments().getString("ciReview"));assertTrue(android.os.Build.HARDWARE.contains("ranchu")||android.os.Build.HARDWARE.contains("goldfish"));Context context=InstrumentationRegistry.getInstrumentation().getTargetContext();assertFalse(AlarmService.active);assertFalse(TrackingService.running);assertFalse(Prefs.flag(context,"ringing"));}
 @Test public void allCategoriesAndManualCorrectionsStayDistinctAndPreserveOriginalEvidence()throws Exception{
  try(FavoriteSoundsFixture f=new FavoriteSoundsFixture()){
   long start=f.night(1,1,60000);Map<String,JSONObject> events=new HashMap<>();int n=0;for(String category:SoundBrowseFilter.CATEGORIES)events.put(category,f.event(1,start+n++*3000,category,true));
   RecordEntry night=Records.get(f.store,1);JSONObject cough=events.get("cough"),noise=events.get("noise");SoundLabels.save(f.store,new SoundLabels.Snapshot(cough,night.updated,night.edit.start,night.edit.end),"speech");SoundLabels.save(f.store,new SoundLabels.Snapshot(noise,night.updated,night.edit.start,night.edit.end),"baby_cry");
   java.io.File wav=f.wav();byte[] original=Files.readAllBytes(wav.toPath());f.store.clip(1,start+30000,wav.getName(),.2,10000);JSONObject clip=f.store.rows("SELECT * FROM clips").get(0);SoundClips.favorite(f.store,clip,true);
   String before=f.store.rows("SELECT * FROM sound_events ORDER BY id").toString();FavoriteSoundRows.Page all=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"all"),0,f.now);assertEquals(7,all.total);Map<String,Integer> expected=Map.of("snoring",1,"speech",2,"cough",0,"baby_cry",2,"laughter",1,"noise",1);List<SoundEventRows.Row> rows=SoundEventRows.metadata(f.context,f.store,night);
   for(String category:SoundBrowseFilter.CATEGORIES){int amount=expected.get(category);assertEquals(category,amount,all.count(category));FavoriteSoundRows.Page page=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,category),0,f.now);assertEquals(category,amount,page.total);assertEquals(amount,page.items.size());assertEquals(amount,SoundEventRows.prepare(f.context,f.store,rows,category,50).size());for(FavoriteSoundRows.Item item:page.items)assertEquals(category,SoundBrowseFilter.category(item.row.category));}
   assertEquals(7,SoundEventRows.prepare(f.context,f.store,rows,"favorites",50).size());assertEquals(before,f.store.rows("SELECT * FROM sound_events ORDER BY id").toString());JSONObject changed=f.store.rows("SELECT * FROM sound_events WHERE id=?",""+cough.getLong("id")).get(0);assertEquals("cough",changed.getString("category"));assertEquals(cough.getDouble("score"),changed.getDouble("score"),0);assertEquals(cough.getString("model"),changed.getString("model"));assertEquals(cough.getLong("time"),changed.getLong("time"));assertEquals(cough.getLong("duration_ms"),changed.getLong("duration_ms"));assertEquals("Speech · Your label",SoundLabels.title(changed));assertArrayEquals(original,Files.readAllBytes(wav.toPath()));
  }
 }
 @Test public void perCategoryPagingAndDateCountsAgreeAndCorruptOldOverlayFallsBackToOriginal()throws Exception{
  try(FavoriteSoundsFixture f=new FavoriteSoundsFixture()){
   long recent=f.night(1,1,200000),old=f.night(2,40,30000);for(int n=0;n<51;n++)f.event(1,recent+n*3000,"cough",true);f.event(1,recent+180000,"laughter",true);f.event(2,old+1000,"cough",true);
   f.store.getWritableDatabase().execSQL("UPDATE sound_events SET user_category='unknown-old-overlay' WHERE category='laughter'");
   FavoriteSoundRows.Page first=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(7,"cough"),0,f.now),last=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(7,"cough"),1,f.now);assertEquals(51,first.total);assertEquals(50,first.items.size());assertEquals(1,last.items.size());assertEquals(52,first.count("all"));assertEquals(1,first.count("laughter"));assertEquals(0,first.count("noise"));Set<String> keys=new HashSet<>();for(FavoriteSoundRows.Item item:first.items)assertTrue(keys.add(item.row.key));assertTrue(keys.add(last.items.get(0).row.key));assertEquals(52,FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(0,"cough"),0,f.now).total);assertEquals(0,FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(7,"baby_cry"),0,f.now).total);
   FavoriteSoundRows.Page laughter=FavoriteSoundRows.read(f.context,f.store,new FavoriteSoundRows.Filter(7,"laughter"),0,f.now);assertEquals("Laughter estimate",laughter.items.get(0).row.title);assertEquals(53,f.store.rows("SELECT * FROM sound_events").size());
  }
 }
}
